from pathlib import Path
import subprocess
base = Path('samples/a.bin').read_bytes()
mut = Path('/tmp/mut.bin')

def cks(body):
    x = 0
    for i in range(0, len(body), 4):
        x ^= int.from_bytes(body[i:i+4].ljust(4, b'\0'), 'little')
    return x.to_bytes(4, 'little')

def rd(data):
    mut.write_bytes(data)
    return subprocess.run(['./reader', str(mut)], capture_output=True, text=True).stdout.strip()

def ok(data):
    return rd(data) != 'INVALID'

def fixed(body):
    return body + cks(body)

def ranges(vals):
    vals = sorted(vals); out=[]
    for v in vals:
        if not out or v > out[-1][1]+1: out.append([v,v])
        else: out[-1][1]=v
    return ' '.join(f'{a:02x}' if a==b else f'{a:02x}-{b:02x}' for a,b in out)

print('BASE', rd(base))
print('TRAILER_MATCH', cks(base[:-4]).hex(), base[-4:].hex())
print('VALID_TRUNCS', [i for i in range(len(base)+1) if ok(base[:i])])
for i in list(range(9)) + list(range(65,69)):
    d=bytearray(base); d[i]^=1
    print(f'flip[{i}]', rd(d))
print('count0', rd(fixed(base[:8] + b'\x00' + base[9:17])))
