for c in [3,8,9,255]:
    rec = b'\x01A\x01B\x01C\x00'
    body = base[:8] + bytes([c]) + base[9:17] + rec * c
    print(f'countN{c}', rd(fixed(body)))

fields = {'code': (17,18,30), 'category': (30,31,46), 'created': (46,47,53)}
for name,(li,start,end) in fields.items():
    good=[]
    for ch in range(256):
        d=bytearray(base); d[start]=ch
        if ok(fixed(d[:-4])): good.append(ch)
    print(name+'_charset', ranges(good), 'n='+str(len(good)))
    good=[]
    for n in range(256):
        body=base[:li]+bytes([n])+b'A'*n+base[end:-4]
        if ok(fixed(body)): good.append(n)
    print(name+'_lengths', ranges(good), 'n='+str(len(good)))
for v in [0,1,255]:
