MAGIC = b"\xc0\x9d\xb4\x05\x83"


def parse(data: bytes) -> dict | None:
    if not isinstance(data, (bytes, bytearray, memoryview)):
        return None
    data = bytes(data)
    if len(data) > 65536 or len(data) < 16:
        return None
    end = len(data) - 4
    if data[:5] != MAGIC or data[5:8] != b"\x00\x00\x00":
        return None
    count = data[8]
    if count > 8 or (sum(data[:end]) & 0xFFFFFFFF) != int.from_bytes(data[end:], "little"):
        return None
    flags = int.from_bytes(data[9:11], "big")
    status = data[11]
    pos = 12

    def varint():
        nonlocal pos
        value = 0
        for i in range(5):
            if pos >= end:
                return None
            byte = data[pos]
            pos += 1
            if i == 4 and byte > 0x0F:
                return None
            value |= (byte & 0x7F) << (7 * i)
            if byte < 0x80:
                if i and (byte & 0x7F) == 0:
                    return None
                return value
        return None

    sequence = varint()
    if sequence is None:
        return None
    header = {"flags": flags, "sequence": sequence, "status": status}
    has_item_count = bool(flags & 0x40)

    def text():
        nonlocal pos
        if pos >= end:
            return None
        size = data[pos]
        pos += 1
        if pos + size > end:
            return None
        raw = data[pos:pos + size]
        pos += size
        if any(byte < 0x20 or byte > 0x7E for byte in raw):
            return None
        return raw.decode("ascii")

    records = []
    for _ in range(count):
        score = varint()
        region = text()
        if score is None or region is None or pos + 4 > end:
            return None
        checksum = int.from_bytes(data[pos:pos + 2], "little")
        source = int.from_bytes(data[pos + 2:pos + 4], "big")
        pos += 4
        record = {"checksum": checksum, "region": region, "score": score, "source": source}
        if has_item_count:
            item_count = text()
            if item_count is None:
                return None
            record["item_count"] = item_count
        records.append(record)
    if pos != end:
        return None
    return {"header": header, "records": records}
