MAGIC = b"\xcf\xcb\xcc\x03"


def _checksum(data):
    value = 0
    for offset in range(0, len(data), 4):
        value ^= int.from_bytes(data[offset:offset + 4], "little")
    return value


def parse(data: bytes) -> dict | None:
    if not isinstance(data, (bytes, bytearray, memoryview)):
        return None
    data = bytes(data)
    if len(data) > 65536 or len(data) < 12:
        return None
    end = len(data) - 4
    if data[:4] != MAGIC or data[4] != 0xB0:
        return None
    if int.from_bytes(data[end:], "little") != _checksum(data[:end]):
        return None
    count = int.from_bytes(data[5:7], "little")
    if count > 8:
        return None

    pos = 7

    def take(n):
        nonlocal pos
        if pos + n > end:
            return None
        out = data[pos:pos + n]
        pos += n
        return out

    def text():
        raw = take(1)
        if raw is None:
            return None
        raw = take(raw[0])
        if raw is None or any(c < 0x20 or c > 0x7e for c in raw):
            return None
        return raw.decode("ascii")

    amount = text()
    if amount is None:
        return None
    records = []
    for _ in range(count):
        length = text()
        label = take(1)
        category = text()
        if length is None or label is None or category is None:
            return None
        records.append({"category": category, "label": label[0], "length": length})
    if pos != end:
        return None
    return {"header": {"amount": amount}, "records": records}
