_MAGIC = b'\x95\x31\xf4\xa4\x90'
_MOD = 0xBCA9


def parse(data):
    n = len(data)
    if n < 17:
        return None
    s1, s2 = 1, 0
    for x in data[:-4]:
        s1 = (s1 + x) % _MOD
        s2 = (s2 + s1) % _MOD
    if ((s2 << 16) | s1) != int.from_bytes(data[-4:], 'little'):
        return None
    if data[:5] != _MAGIC:
        return None
    count = int.from_bytes(data[5:9], 'little')
    if count > 8:
        return None
    source = int.from_bytes(data[9:13], 'big')
    pos, end, records = 13, n - 4, []
    for _ in range(count):
        if pos >= end:
            return None
        alen = data[pos]; pos += 1
        if pos + alen > end:
            return None
        amount = data[pos:pos + alen]
        pos += alen
        if any(c < 0x20 or c > 0x7E for c in amount):
            return None
        if pos >= end:
            return None
        plen = data[pos]; pos += 1
        if pos + plen > end:
