MAGIC = b"\x85\x03\x68\x54\x26"
MOD = 0xBEC6


def _checksum(data):
    s1 = 1
    s2 = 0
    for byte in data:
        s1 = (s1 + byte) % MOD
        s2 = (s2 + s1) % MOD
    return (s2 << 16) | s1


def parse(data: bytes) -> dict | None:
    if not isinstance(data, (bytes, bytearray, memoryview)):
        return None
    data = bytes(data)
    if len(data) > 65536 or len(data) < 21:
        return None
    end = len(data) - 4
    if data[:5] != MAGIC or data[5:8] != b"\x00\x00\x00":
        return None
    if int.from_bytes(data[end:], "little") != _checksum(data[:end]):
        return None
    count = data[8]
    if count > 8:
        return None
    header = {
        "rating": int.from_bytes(data[15:17], "big"),
        "source": int.from_bytes(data[11:15], "big"),
        "status": int.from_bytes(data[9:11], "big"),
    }
    pos = 17

    def text():
        nonlocal pos
        if pos >= end:
            return None
        size = data[pos]
        pos += 1
        if pos + size > end:
            return None
        raw = data[pos:pos + size]
        pos += size
        if any(byte < 0x20 or byte > 0x7E for byte in raw):
            return None
        return raw.decode("ascii")

    records = []
    for _ in range(count):
        item_count = text()
        status = text()
        if item_count is None or status is None or pos + 4 > end:
            return None
        version = int.from_bytes(data[pos:pos + 4], "little")
        pos += 4
        records.append({"item_count": item_count, "status": status, "version": version})
    if pos != end:
        return None
    return {"header": header, "records": records}
