MAGIC = b"\x74\x30\x69\x8d\xe0\x00\x00\x00"
MOD = 0x3352


def _checksum(data):
    s1 = 1
    s2 = 0
    for byte in data:
        s1 = (s1 + byte) % MOD
        s2 = (s2 + s1) % MOD
    return (s2 << 16) | s1


def parse(data: bytes) -> dict | None:
    if not isinstance(data, (bytes, bytearray, memoryview)):
        return None
    data = bytes(data)
    if len(data) > 65536 or len(data) < 15:
        return None
    end = len(data) - 4
    if data[:8] != MAGIC:
        return None
    count = data[8]
    if count > 8 or int.from_bytes(data[end:], "little") != _checksum(data[:end]):
        return None
    header_id = data[9]
    pos = 10

    def text():
        nonlocal pos
        if pos >= end:
            return None
        size = data[pos]
        pos += 1
        if pos + size > end:
            return None
        raw = data[pos:pos + size]
        pos += size
        if any(byte < 0x20 or byte > 0x7E for byte in raw):
            return None
        return raw.decode("ascii")

    score = text()
    if score is None or pos >= end:
        return None
    checksum = data[pos]
    pos += 1
    header = {"checksum": checksum, "id": header_id, "score": score}

    records = []
    for _ in range(count):
        code = text()
        if code is None or pos + 6 > end:
            return None
        qty = int.from_bytes(data[pos:pos + 4], "big")
        category = int.from_bytes(data[pos + 4:pos + 6], "little")
        pos += 6
        records.append({"category": category, "code": code, "qty": qty})
    if pos != end:
        return None
    return {"header": header, "records": records}
