MAGIC = b'\x7d\xc0\x06\xe4\x7d'


def _text(data: bytes, pos: int) -> tuple[str, int] | None:
    if pos >= len(data):
        return None
    end = pos + 1 + data[pos]
    if end > len(data):
        return None
    raw = data[pos + 1:end]
    if any(byte < 0x20 or byte > 0x7e for byte in raw):
        return None
    return raw.decode('ascii'), end


def parse(data: bytes) -> dict | None:
    if not isinstance(data, (bytes, bytearray)) or len(data) < 12:
        return None
    data = bytes(data)
    if data[:5] != MAGIC or data[6] != 0:
        return None
    count = data[5]
    if count > 8:
        return None
    price_cents = data[7]
    zone = int.from_bytes(data[8:10], 'big')
    priority = int.from_bytes(data[10:12], 'big')
    pos = 12
    records = []
    for _ in range(count):
        item = _text(data, pos)
        if item is None:
            return None
        label, pos = item
        if pos + 4 > len(data):
            return None
        flags = int.from_bytes(data[pos:pos + 4], 'big')
        pos += 4
        item = _text(data, pos)
        if item is None:
            return None
        version, pos = item
        if pos >= len(data):
            return None
        temperature = data[pos]
        pos += 1
        records.append({'flags': flags, 'label': label, 'temperature': temperature, 'version': version})
    if pos != len(data):
        return None
    return {'header': {'price_cents': price_cents, 'priority': priority, 'zone': zone}, 'records': records}
