def _xor32(d):
    x = 0
    for i in range(0, len(d), 4):
        x ^= int.from_bytes(d[i:i+4].ljust(4, b'\x00'), 'little')
    return x


def parse(data: bytes):
    data = bytes(data)
    if len(data) < 16 or data[:5] != b'WH!Td' or data[6] != 0:
        return None
    end = len(data) - 4
    if int.from_bytes(data[end:], 'little') != _xor32(data[:end]):
        return None
    count = data[5]
    amount = int.from_bytes(data[7:11], 'little')
    qty = data[11]
    pos = 12
    records = []
    for _ in range(count):
        if pos >= end:
            return None
        n = data[pos]; pos += 1
        if pos + n + 1 > end:
            return None
        s = data[pos:pos+n]; pos += n
        if any(c < 0x20 or c > 0x7e for c in s):
            return None
        records.append({'account_id': data[pos], 'label': s.decode('ascii')})
        pos += 1
    if pos != end:
        return None
    return {'header': {'amount': amount, 'qty': qty}, 'records': records}
