def parse(data):
    n = len(data)
    if n < 15 or n > 0x10000 or data[:4] != b'\xf3\xd3\xdb\x6e' or data[4] != 0x2E:
        return None
    end = n - 4
    c, s = 1, 0
    for x in data[:end]:
        c = (c + x) % 31842
        s = (s + c) % 31842
    if int.from_bytes(data[end:], 'little') != (s << 16 | c):
        return None
    count = int.from_bytes(data[5:9], 'big')
    if count > 8:
        return None
    flags = int.from_bytes(data[9:11], 'big')
    pos = 11
    def rstr():
        nonlocal pos
        if pos >= end:
            return None
        ln = data[pos]; pos += 1
        if ln > end - pos:
            return None
        seg = data[pos:pos + ln]; pos += ln
        if any(x < 0x20 or x > 0x7E for x in seg):
            return None
        return seg.decode('latin1')
    def rvar():
        nonlocal pos
        rem = end - pos
        if rem <= 0:
            return None
        acc = 0
        for i in range(5):
            if i >= rem:
                return None
            b = data[pos + i]
            if i == 4:
                if not 1 <= b <= 0x0F:
                    return None
                pos += 5
                return acc | (b << 28)
            acc |= (b & 0x7F) << (7 * i)
            if not b & 0x80:
                if b == 0 and i > 0:
                    return None
                pos += i + 1
                return acc
    hdr_status = rstr()
    if hdr_status is None:
        return None
    hdr_temp = rstr()
    if hdr_temp is None:
        return None
    recs = []
    for _ in range(count):
        pri = rvar()
        amt = rstr()
        sta = rvar()
        if pri is None or amt is None or sta is None:
            return None
        rec = {'amount': amt, 'priority': pri, 'status': sta}
        if flags & 0x80:
            if end - pos < 4:
                return None
            rec['category'] = int.from_bytes(data[pos:pos + 4], 'big')
            pos += 4
        recs.append(rec)
    if pos != end:
        return None
    return {'header': {'flags': flags, 'status': hdr_status, 'temperature': hdr_temp}, 'records': recs}
