MAGIC = b'\x22\x39\x7a\xf8\x2a'


def _text(data: bytes, pos: int) -> tuple[str, int] | None:
    if pos >= len(data):
        return None
    end = pos + 1 + data[pos]
    if end > len(data):
        return None
    raw = data[pos + 1:end]
    if any(byte < 0x20 or byte > 0x7e for byte in raw):
        return None
    return raw.decode('ascii'), end


def parse(data: bytes) -> dict | None:
    if not isinstance(data, (bytes, bytearray)) or len(data) < 15:
        return None
    data = bytes(data)
    if data[:5] != MAGIC or data[5] != 0:
        return None
    count = data[6]
    if count > 8:
        return None
    amount = int.from_bytes(data[7:9], 'little')
    priority = int.from_bytes(data[9:13], 'little')
    enabled = int.from_bytes(data[13:15], 'little')
    pos = 15
    records = []
    for _ in range(count):
        item = _text(data, pos)
        if item is None:
            return None
        zone, pos = item
        if pos >= len(data):
            return None
        balance = data[pos]
        pos += 1
        item = _text(data, pos)
        if item is None:
            return None
        account_id, pos = item
        item = _text(data, pos)
        if item is None:
            return None
        version, pos = item
        records.append({'account_id': account_id, 'balance': balance, 'version': version, 'zone': zone})
    if pos != len(data):
        return None
    return {'header': {'amount': amount, 'enabled': enabled, 'priority': priority}, 'records': records}
